export function getRandomInt(max){return Math.floor(Math.random()*Math.floor(max))}export function selectContainsOptionValue(select,value){const options=select.options,length=options.length;for(let i=0;i<length;i++)if(options[i].value===value)return!0;return!1}export function isDataComplex(val){return(Array.isArray(val)||"object"==typeof val)&&null!==val}export function compareObjectsRecursion(oldObj,newObj,changes){for(const key in newObj){const n=newObj[key],ncomplex="object"==typeof n&&null!==n;if(void 0===oldObj||!ncomplex&&oldObj[key]!==n)changes[key]=ncomplex?JSON.parse(JSON.stringify(n)):n;else if(ncomplex){let tmp;tmp=Array.isArray(n)?[]:{},compareObjectsRecursion(oldObj[key],n,tmp)&&(changes[key]=tmp)}}for(const k in changes)if(changes.hasOwnProperty(k))return changes;return!1}export function compareObjects(oldObj,newObj){const changes={};return compareObjectsRecursion(oldObj,newObj,changes),changes}export function baseConverter(num,baseFrom,baseTo){return parseInt(num,baseFrom).toString(baseTo)}export function fillStringToLength(character,numOfCharacters,stringToFillUp){return(character.repeat(numOfCharacters)+stringToFillUp).substr(-numOfCharacters)}export function removeNotConnectedDomElements(domElements){for(const domElement of domElements.keys())domElement.isConnected||domElements.delete(domElement)}export function toHexString(dec){return(dec<0?"-":"")+"0x"+Math.abs(dec).toString(16)}export function isoWeekDateToDateString(year,calendarWeek,dayOfWeek){if(calendarWeek<1||calendarWeek>53||dayOfWeek<1||dayOfWeek>7)return null;const jan4=new Date(Date.UTC(year,0,4)),jan4DayOfWeek=0===jan4.getUTCDay()?7:jan4.getUTCDay(),week1Monday=Date.UTC(year,0,4-(jan4DayOfWeek-1)),date=new Date(week1Monday+864e5*(7*(calendarWeek-1)+(dayOfWeek-1))),month=fillStringToLength("0",2,(date.getUTCMonth()+1).toString()),day=fillStringToLength("0",2,date.getUTCDate().toString());return`${date.getUTCFullYear()}-${month}-${day}`}